#!/usr/bin/env bash
# Выносит падения тестов туда, где их видно без прав администратора.
#
# Зачем это нужно. Логи прогона GitHub отдаёт только по токену с правами
# администратора репозитория: `GET /actions/jobs/{id}/logs` без них отвечает
# «Must have admin rights to Repository», а deploy key таких прав не даёт вовсе.
# Публично при красном прогоне видно ровно две вещи — имя шага и «Process
# completed with exit code 1». Разбор превращается в угадывание: 2026-07-30
# падение матрицы py3.14 и тестов в образе пришлось воспроизводить локально
# вслепую, и локально всё было зелено.
#
# Аннотации и сводка прогона, в отличие от логов, доступны каждому, кто видит
# репозиторий (`/check-runs/{id}/annotations`). Значит текст падения надо
# положить туда — тогда причина читается сразу и из браузера, и из API.
#
# Отчёт привязан к коду возврата pytest, а не к тексту его вывода. Искать в
# выводе `FAILED` значило бы пропустить ровно те случаи, которые труднее всего
# разобрать: аварийный код 2–5, падение самого интерпретатора, прерванный
# прогон, «no tests collected». Поймано на ревью Codex.
set -euo pipefail

label="${1:?нужна метка прогона}"
log="${2:?нужен файл с выводом pytest}"
status_file="${3:?нужен файл с кодом возврата pytest}"

if [ ! -f "$status_file" ]; then
    # Шаг вызывается по `if: failure()`, а упасть мог и шаг до тестов — тогда
    # pytest не запускался. Это не повод валить job второй раз.
    echo "pytest не запускался, отчёт не нужен: нет $status_file"
    exit 0
fi

status="$(cat "$status_file")"
if [ "$status" = "0" ]; then
    # В job-е с образом после тестов идут ещё шаги, и упасть может любой из них.
    # Зелёный прогон тестов в отчёт о падениях попадать не должен.
    echo "тесты прошли, упало что-то после них — отчёт не нужен"
    exit 0
fi

# Хвост, а не весь файл: нужное — сводка `-rf` и короткие трассировки — всегда в
# конце вывода. Ограничение и по строкам, и по байтам: сообщение аннотации
# GitHub обрезает на 64 KiB, а сорок строк — это не сорок коротких строк, одна
# может оказаться огромной. `iconv -c` убирает символ, разрезанный на границе.
tail_text="вывода нет"
if [ -s "$log" ]; then
    tail_text="$(tail -n 40 "$log" | tail -c 20000 | iconv -c -f UTF-8 -t UTF-8)"
fi
report="pytest завершился с кодом $status"$'\n'"$tail_text"

if [ -n "${GITHUB_STEP_SUMMARY:-}" ]; then
    # Ограда длиннее самой длинной цепочки обратных кавычек в тексте: строка с
    # ``` внутри трассировки закрыла бы блок, и остаток вывода отрисовался бы
    # как разметка. Тоже с ревью Codex.
    # `|| true` обязателен: без кавычек в тексте `grep` возвращает 1, а с
    # `pipefail` это уронило бы весь скрипт — то есть отчёт пропал бы ровно
    # тогда, когда вывод самый простой.
    longest="$(printf '%s' "$report" | { grep -o '`\+' || true; } \
        | awk '{ if (length($0) > n) n = length($0) } END { print n + 0 }')"
    fence_length=3
    if [ "$longest" -ge 3 ]; then
        fence_length=$((longest + 1))
    fi
    fence="$(printf '`%.0s' $(seq "$fence_length"))"
    {
        printf '### %s — падения\n\n' "$label"
        printf '%s\n%s\n%s\n' "$fence" "$report" "$fence"
    } >>"$GITHUB_STEP_SUMMARY"
fi

# Перевод строки в команде workflow значил бы конец команды, поэтому переносы
# экранируются. Процент — первым: иначе замена испортит уже подставленные `%0A`.
escaped="${report//'%'/%25}"
escaped="${escaped//$'\r'/%0D}"
escaped="${escaped//$'\n'/%0A}"
printf '::error title=%s::%s\n' "$label" "$escaped"
